import {buildMappingGraph,traceAsset,readEvidence} from './model.mjs';
import {entities,relations,rules,fields,apis,entityFields} from './catalog.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=(title,body)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2></div>${body}</section>`;
const opt=(id,label,current)=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`;
const tag=(v,warn=false)=>`<span class="tag ${warn?'medium':''}">${esc(v)}</span>`;
const button=(label,attr)=>`<button type="button" class="text-link quiet" ${attr}>${esc(label)}</button>`;
const diagrams={
 ownership:['application','application_service','service','source_binding','project','environment','workload'],
 delivery:['project','commit','pipeline','job','artifact','sbom','gitlab_environment','deployment'],
 runtime:['account','region','cluster','ecs_service','task_definition','workload','ecr_image','artifact','lambda_function','lambda_alias','inventory'],
 evidence:['commit','source_file','sbom','component','observation','inventory','workload'],
};
export function createMappingView({getFleet,getInput,getRepositories,onProfileChange,onChange,openDialog,inspectAsset}){
 let tab='overview',entity='application',search='',source='all',diagram='ownership',assetId='',appId='all',environment='all',cachedFleet=null,graph=null;
 const getGraph=()=>{const fleet=getFleet();if(cachedFleet!==fleet){graph=buildMappingGraph(fleet,getInput(),getRepositories());cachedFleet=fleet;}return graph;};
 const bundle=()=>({snapshot:getFleet().snapshot,capture:getInput(),repositories:getRepositories()});
 const filteredAssets=()=>getFleet().assets.filter(a=>(appId==='all'||a.app?.id===appId)&&(environment==='all'||a.environment===environment));
 function currentAsset(){const assets=filteredAssets();return assets.find(a=>a.id===assetId)||assets[0];}
 const label=t=>entities.find(e=>e[0]===t)?.[1]||t;
 function evidenceHTML(provenance){return provenance?.length?provenance.map(e=>`<details><summary>${esc(e.meaning)} · ${esc(e.source+e.pointer)}</summary><p class="footnote">Captured ${esc(e.capturedAt||getInput().captured_at)} · simulated source</p><pre>${esc(JSON.stringify(readEvidence(bundle(),e),null,2)??'Record not captured')}</pre></details>`).join(''):'<p class="footnote">Derived identity or configured normalization; inspect adjacent relationship evidence.</p>';}
 function inspectNode(key){const g=getGraph(),n=g.nodes.find(n=>n.id===key);if(!n)return;const links=g.edges.filter(e=>e.from===key||e.to===key);openDialog(`<div class="eyebrow">CANONICAL ENTITY · ${esc(n.type)}</div><h2>${esc(n.label)}</h2><pre>${esc(n.id)}</pre><h3>Normalized attributes</h3><pre>${esc(JSON.stringify(n.attributes,null,2))}</pre><h3>Native evidence</h3>${evidenceHTML(n.provenance)}<h3>Relationships · ${links.length}</h3>${edgeTable(links)}<p class="footnote">Canonical IDs are scoped identities. They are never joined by their display labels.</p>`);bindInspect();}
 function inspectEdge(key){const e=getGraph().edges.find(e=>e.id===key);if(!e)return;const r=relations.find(r=>r[0]===e.type),rule=rules.find(r=>r[0]===e.rule);openDialog(`<div class="eyebrow">RELATIONSHIP ASSERTION</div><h2>${esc(e.type)}</h2><p>${tag(r[3])} ${tag(e.rule)}</p><p>${esc(r[4])}</p><pre>${esc(e.from)}\n→ ${esc(e.to)}</pre><h3>Join policy</h3><p>${esc(rule?.[2])}</p><h3>Relationship attributes</h3><pre>${esc(JSON.stringify(e.attributes,null,2))}</pre><h3>Native evidence</h3>${evidenceHTML(e.provenance)}`);}
 function bindInspect(){document.querySelectorAll('[data-map-node]').forEach(b=>b.onclick=()=>inspectNode(b.dataset.mapNode));document.querySelectorAll('[data-map-edge]').forEach(b=>b.onclick=()=>inspectEdge(b.dataset.mapEdge));}
 function nodeTable(nodes){return `<div class="table-wrap"><table class="mapping-table"><thead><tr><th>Entity</th><th>Record</th><th>Canonical key</th><th>Evidence</th></tr></thead><tbody>${nodes.slice(0,100).map(n=>`<tr><td>${tag(label(n.type))}</td><td>${button(n.label,`data-map-node="${esc(n.id)}"`)}</td><td><code>${esc(n.id)}</code></td><td>${n.provenance.length} source record(s)</td></tr>`).join('')||'<tr><td colspan="4">No records in this scope.</td></tr>'}</tbody></table></div>${nodes.length>100?`<p class="footnote">Showing 100 of ${nodes.length}. Filter further or export the full graph.</p>`:''}`;}
 function edgeTable(edges){const map=new Map(getGraph().nodes.map(n=>[n.id,n]));return `<div class="table-wrap"><table class="mapping-table"><thead><tr><th>Relationship / rule</th><th>From</th><th>To</th></tr></thead><tbody>${edges.slice(0,150).map(e=>`<tr><td>${button(e.type,`data-map-edge="${esc(e.id)}"`)}<small>${esc(e.rule)}</small></td><td>${esc(map.get(e.from)?.label||e.from)}</td><td>${esc(map.get(e.to)?.label||e.to)}</td></tr>`).join('')}</tbody></table></div>${edges.length>150?'<p class="footnote">Showing 150 relationships. Full graph available in export.</p>':''}`;}
 function schemaDiagram(){
  const group=diagrams[diagram],cols=diagram==='runtime'?4:3,width=cols*280+40,rows=Math.ceil(group.length/cols),height=rows*170+30;
  const positions=new Map(group.map((type,i)=>[type,{x:20+(i%cols)*280,y:20+Math.floor(i/cols)*170}]));
  const included=relations.filter(r=>positions.has(r[1])&&positions.has(r[2])&&r[1]!==r[2]);
  return `<div class="mapping-diagram"><svg viewBox="0 0 ${width} ${height}" width="${width}" role="img" aria-label="${esc(diagram)} entity relationship diagram"><defs><marker id="map-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9aafa0"/></marker></defs>${included.map(r=>{const a=positions.get(r[1]),b=positions.get(r[2]);return `<path d="M${a.x+118},${a.y+105} C${a.x+118},${a.y+135} ${b.x+118},${b.y-22} ${b.x+118},${b.y}" stroke="#a8b9a9" fill="none" marker-end="url(#map-arrow)"><title>${esc(r[0]+' · '+r[3])}</title></path>`;}).join('')}${group.map(type=>{const {x,y}=positions.get(type),count=getGraph().nodes.filter(n=>n.type===type).length;return `<g tabindex="0" role="button" aria-label="Explore ${esc(label(type))}" data-map-type="${type}"><rect x="${x}" y="${y}" width="238" height="105" rx="8" fill="${['application','project','workload'].includes(type)?'#215d47':'#f2f6ed'}" stroke="#bdd0bc"/><text x="${x+14}" y="${y+27}" fill="${['application','project','workload'].includes(type)?'white':'#19332d'}" font-size="13" font-weight="600">${esc(label(type))}</text><text x="${x+14}" y="${y+48}" fill="${['application','project','workload'].includes(type)?'#d7e9c9':'#657c68'}" font-size="11">${count} captured records · click to explore</text><text x="${x+14}" y="${y+68}" fill="${['application','project','workload'].includes(type)?'#d7e9c9':'#657c68'}" font-size="10">PK id · ${esc(entityFields[type].filter(f=>f[2]==='FK').map(f=>f[0]).slice(0,1).join(', ')||entityFields[type][0][0])}</text><text x="${x+14}" y="${y+87}" fill="${['application','project','workload'].includes(type)?'#d7e9c9':'#657c68'}" font-size="10">${esc(entityFields[type].filter(f=>f[2]!=='FK').map(f=>f[0]).slice(1,3).join(' · '))}</text></g>`;}).join('')}</svg></div><p class="footnote">Arrows show relationship direction. Exact cardinalities and join policies are listed below; click an entity to inspect its records.</p><div class="table-wrap"><table class="mapping-table"><thead><tr><th>From → to</th><th>Cardinality</th><th>Relationship / join</th></tr></thead><tbody>${included.map(r=>`<tr><td>${esc(label(r[1]))} → ${esc(label(r[2]))}</td><td>${esc(r[3])}</td><td><strong>${esc(r[0])}</strong><small>${esc(r[4])} · ${r[5]}</small></td></tr>`).join('')}</tbody></table></div>`;
 }
 function overview(){const g=getGraph(),fleet=getFleet();return `<div class="stats">${[['Canonical entity types',entities.length],['Captured records',g.nodes.length],['Relationship assertions',g.edges.length],['Mapping unresolved/conflicting',fleet.assets.filter(a=>a.mapping?.status!=='resolved').length]].map(([l,n])=>`<div class="stat"><span class="stat-label">${l}</span><div class="stat-num">${n}</div></div>`).join('')}</div>`+panel('How the systems connect',`<div class="join-flow"><div><b>ServiceNow</b><span>Business app → application service</span></div><i>→</i><div><b>Mapping registry</b><span>Service → project + source path</span></div><i>→</i><div><b>GitLab</b><span>Commit → pipeline → job → artifact</span></div><i>←</i><div><b>AWS observation</b><span>Workload → digest / code hash</span></div></div><p class="section-note">The selected profile drives the application, deployed-version and environment-matrix views. Open a workload trace to inspect each join and its native evidence. The model includes shared application services, multiple source bindings, repeated builds, mixed rollouts and explicit gaps.</p><div class="mapping-actions"><button class="button primary" data-map-tab="trace">Trace an actual simulated workload →</button><button class="button" data-map-tab="erd">Explore ERDs</button><button class="button" data-map-tab="fields">Read native field mappings</button></div>`)+panel('Modeled scenarios',`<div class="scenario-grid">${getInput().scenarios.map(s=>`<div><span class="scenario-dot"></span><p>${esc(s.description)}</p></div>`).join('')}</div>`)+panel('Entity dictionary',`<div class="mapping-entity-grid">${entities.map(e=>`<button class="mapping-entity" data-map-type="${e[0]}"><strong>${esc(e[1])}</strong><span>${getGraph().nodes.filter(n=>n.type===e[0]).length} records</span><small>${esc(e[4])}</small></button>`).join('')}</div>`);}
 function trace(){const a=currentAsset();if(!a)return panel('Workload trace','<p>No workloads match these filters.</p>');assetId=a.id;const t=traceAsset(getGraph(),a),m=a.mapping;const groups=[['Application / service',['application','application_service','service','source_binding']],['Source / build',['project','commit','pipeline','job']],['Artifact / SBOM',['artifact','sbom']],['AWS placement',['account','region','cluster','ecs_service','task_definition','lambda_function','lambda_alias','workload']],['Version evidence',['component','observation','inventory','source_file']]];return panel('Select a workload to trace',`<div class="mapping-filters"><label>Business application<select id="map-app">${opt('all','All applications',appId)}${getFleet().apps.map(a=>opt(a.id,a.name,appId)).join('')}</select></label><label>Environment<select id="map-env">${opt('all','All environments',environment)}${['dev','uat','prod'].map(e=>opt(e,e.toUpperCase(),environment)).join('')}</select></label><label>Observed workload<select id="map-asset">${filteredAssets().map(a=>opt(a.id,`${a.service} · ${a.environment.toUpperCase()} · ${a.kind} · ${a.resourceId.slice(-10)}`,assetId)).join('')}</select></label></div>`)+panel('Cross-system lineage',`<p>${tag(m.status,m.status!=='resolved')} ${tag(a.coverage==='artifact'?'Artifact inventory':a.coverage==='host'?'Host inventory':'Inventory gap',a.coverage==='gap')} ${tag(a.environment.toUpperCase())}</p><p class="section-note">${esc(a.resourceId)}</p><div class="mapping-lineage">${groups.map(([title,types])=>{const ns=t.nodes.filter(n=>types.includes(n.type));return `<div><h3>${title}</h3>${ns.slice(0,8).map(n=>`<p>${button(n.label,`data-map-node="${esc(n.id)}"`)}<small>${esc(label(n.type))}</small></p>`).join('')||'<p class="risk">No validated link</p>'}${ns.length>8?`<small>${ns.length-8} more records in the table below</small>`:''}</div>`;}).join('')}</div><p class="footnote">Source evidence stays attached to its commit. GitLab deployment intent never replaces the observed artifact. An unresolved ownership mapping can still have independently observed AWS identity.</p><button class="button" id="map-inspect-asset">Open deployed-version evidence</button><details><summary>Mapping decision and rule evidence</summary><pre>${esc(JSON.stringify(m,null,2))}</pre>${evidenceHTML(m.evidence)}</details>`)+panel('Trace issues',t.issues.length?`<ul>${t.issues.map(i=>`<li><strong>${esc(i.code)}</strong> — ${esc(i.message)}</li>`).join('')}</ul>`:'<p>No mapping or inventory gaps recorded on this trace. Completeness still depends on captured sources.</p>')+panel(`Relationships in this trace · ${t.edges.length}`,edgeTable(t.edges))+panel(`Records in this trace · ${t.nodes.length}`,nodeTable(t.nodes));}
 function records(){const g=getGraph(),q=search.toLowerCase(),ns=g.nodes.filter(n=>(entity==='all'||n.type===entity)&&(!q||JSON.stringify(n).toLowerCase().includes(q)));return panel('Canonical records',`<div class="mapping-filters"><label>Entity type<select id="map-entity">${opt('all','All entity types',entity)}${entities.map(e=>opt(e[0],`${e[1]} (${g.nodes.filter(n=>n.type===e[0]).length})`,entity)).join('')}</select></label><label>Search keys, labels or attributes<input id="map-search" value="${esc(search)}" placeholder="sys_id, SHA, ARN, package…"></label></div><p class="section-note">${ns.length} matching records. Select a record for its native source and relationships.</p>${nodeTable(ns)}`);}
 function fieldView(){const rows=fields.filter(f=>source==='all'||f[0]===source);return panel('Native fields → canonical model',`<label class="mapping-source">Source system<select id="map-source">${opt('all','All sources',source)}${[...new Set(fields.map(f=>f[0]))].map(s=>opt(s,s,source)).join('')}</select></label><p class="section-note">Native API fields, organization conventions and derived evidence are distinguished explicitly. Profile configuration controls ownership and environment mapping; these are the actual policies applied by the POC.</p><div class="table-wrap"><table class="mapping-table"><thead><tr><th>Source / ownership</th><th>Native field</th><th>Canonical destination</th><th>Transform / rule</th></tr></thead><tbody>${rows.map(f=>`<tr><td>${esc(f[0])}<small>${esc(f[5])}</small></td><td><code>${esc(f[1])}</code></td><td>${esc(f[2])}</td><td>${esc(f[3])}<small>${esc(f[4])}</small></td></tr>`).join('')}</tbody></table></div>`)+panel('Active executable profile',`<pre>${esc(JSON.stringify(getInput().profiles.find(p=>p.id===getFleet().profileId),null,2))}</pre>`);}
 function erd(){return panel('Entity relationship diagrams',`<div class="version-tabs">${Object.keys(diagrams).map(d=>`<button data-map-diagram="${d}" class="${diagram===d?'selected':''}" aria-pressed="${diagram===d}">${esc(d[0].toUpperCase()+d.slice(1))}</button>`).join('')}</div>${schemaDiagram()}`)+panel('Keys and identity scopes',`<div class="table-wrap"><table class="mapping-table"><thead><tr><th>Entity</th><th>Unique identity</th><th>Native source</th></tr></thead><tbody>${entities.filter(e=>diagrams[diagram].includes(e[0])).map(e=>`<tr><td>${esc(e[1])}</td><td>${esc(e[2])}</td><td>${esc(e[3])}</td></tr>`).join('')}</tbody></table></div>`);}
 function exceptions(){return panel('Mapping and evidence exceptions',`<p class="section-note">Ownership conflicts, missing artifact evidence, rollout differences and missing native references remain visible. These observations have different meanings; a rollout difference is not an ownership conflict.</p><div class="table-wrap"><table class="mapping-table"><thead><tr><th>Code</th><th>Finding</th><th>Subject</th></tr></thead><tbody>${getGraph().issues.map(i=>`<tr><td>${tag(i.code,true)}</td><td>${esc(i.message)}</td><td>${i.assetId?button('Trace workload →',`data-map-asset="${esc(i.assetId)}"`):i.subject?button('Inspect subject →',`data-map-node="${esc(i.subject)}"`):'Build evidence'}</td></tr>`).join('')}</tbody></table></div>`);}
 function apiView(){return panel('Official API collection contract',`<p class="section-note">The POC applies adapters to simulated captures. Live credentials and collection are not configured. Each operation below identifies the official API, permissions and collection behavior; the repository runbook provides concrete requests and sequencing.</p><div class="table-wrap"><table class="mapping-table"><thead><tr><th>Provider / operation</th><th>Request</th><th>Read access</th><th>Collection behavior</th></tr></thead><tbody>${apis.map(a=>`<tr><td><a href="${esc(a[5])}" target="_blank" rel="noopener noreferrer">${esc(a[0]+' · '+a[1])}</a></td><td><code>${esc(a[2])}</code></td><td>${esc(a[3])}</td><td>${esc(a[4])}</td></tr>`).join('')}</tbody></table></div>`)+panel('Join rules',`<div class="mapping-rule-grid">${rules.map(r=>`<article><strong>${esc(r[0]+' · '+r[1])}</strong><p>${esc(r[2])}</p></article>`).join('')}</div>`);}
 function render(){getGraph();return `<div class="simulation-banner"><div><span class="simulation-pill">SIMULATED MAPPING</span><span>ServiceNow ↔ GitLab ↔ AWS</span></div><a class="text-link" href="https://github.com/glnewton/sbom-poc/tree/main/docs/architecture" target="_blank" rel="noopener noreferrer">Technical model & ERDs ↗</a></div><div class="mapping-profile"><label>Active mapping profile<select id="map-profile">${getInput().profiles.map(p=>opt(p.id,p.name,getFleet().profileId)).join('')}</select></label><p>Changing this profile recomputes portfolio mappings and deployed-version results for this session.</p><button class="button" id="map-export">↓ Export canonical graph</button></div><div class="version-tabs mapping-tabs" role="group" aria-label="Mapping workbench views">${[['overview','Overview'],['trace','Workload trace'],['erd','ERDs'],['records','Records'],['fields','Field mappings'],['exceptions','Exceptions'],['apis','Official APIs & rules']].map(([id,title])=>`<button data-map-tab="${id}" class="${tab===id?'selected':''}" aria-pressed="${tab===id}">${title}</button>`).join('')}</div>${({overview,trace,erd,records,fields:fieldView,exceptions,apis:apiView})[tab]()}`;}
 function exportGraph(){const body=JSON.stringify(getGraph(),null,2),url=URL.createObjectURL(new Blob([body],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='canonical-mapping-graph.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function bind(){const $=s=>document.querySelector(s);$('#map-profile')?.addEventListener('change',e=>onProfileChange(e.target.value));$('#map-export')?.addEventListener('click',exportGraph);document.querySelectorAll('[data-map-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.mapTab;onChange();});document.querySelectorAll('[data-map-diagram]').forEach(b=>b.onclick=()=>{diagram=b.dataset.mapDiagram;onChange();});document.querySelectorAll('[data-map-type]').forEach(b=>{const choose=()=>{entity=b.dataset.mapType;search='';tab='records';onChange();};b.onclick=choose;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});
 for(const [selector,assign]of [['#map-entity',v=>entity=v],['#map-source',v=>source=v],['#map-app',v=>{appId=v;assetId='';}],['#map-env',v=>{environment=v;assetId='';}],['#map-asset',v=>assetId=v]])$(selector)?.addEventListener('change',e=>{assign(e.target.value);onChange();});
 $('#map-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;onChange();$('#map-search').focus();$('#map-search').setSelectionRange(pos,pos);});$('#map-inspect-asset')?.addEventListener('click',()=>inspectAsset(assetId));document.querySelectorAll('[data-map-asset]').forEach(b=>b.onclick=()=>{assetId=b.dataset.mapAsset;appId='all';environment='all';tab='trace';onChange();});bindInspect();}
 return {render,bind,export:exportGraph,selectAsset(id){assetId=id;appId='all';environment='all';tab='trace';document.querySelector('#details')?.close();location.hash='mapping';onChange();}};
}
